// 서울 25구 개인파산·면책 안내는 개인파산 카테고리로 별도 발행합니다.
const makeSeoulBankruptcyArticle=(seed:DistrictSeed):Article=>{
  const dongTags=seed.dongs.flatMap(d=>[d+' 개인파산',d+' 개인파산상담',d+' 면책 상담']);
  return {
    id:'bankruptcy-'+seed.slug,
    title:seed.district+' 개인파산·면책 상담 전 확인할 채무·재산 자료',
    category:'개인파산',
    region:'서울',
    district:seed.district,
    dongs:seed.dongs,
    tags:[seed.district+' 개인파산',seed.district+' 개인파산상담',seed.district+' 개인파산신청',seed.district+' 면책',seed.district+' 채무상담',...dongTags],
    date:'2026.09.29',
    image:sharedLegalHeroImage,
    excerpt:seed.district+' 개인파산과 면책 상담 전 채무·재산·소득·가족관계 자료를 정리하는 방법을 안내합니다.',
    body:`${seed.district}에서 개인파산·면책 상담을 알아보는 이유는 단순히 채무가 많아서만은 아닙니다. 반복되는 상환일과 독촉, 생활비 부족으로 일상이 무너지는 상황이라면 현재의 채무 구조를 객관적으로 점검하고 가능한 제도를 차분히 확인해 볼 필요가 있습니다. 개인파산과 면책은 각각의 재산·소득·채무 발생 경위에 따라 검토되므로, 먼저 정확한 사실관계를 정리하는 것이 출발점입니다.

상담 전에는 카드·대출·보증 채무를 채권자별로 정리하고, 최근 소득과 지출, 임대차 계약, 예금·보험·차량·부동산 등 재산 자료를 한 곳에 모아 보세요. 가족관계와 부양 상황, 최근 재산 변동이나 채무가 생긴 이유도 날짜 순으로 기록하면 상담에서 빠진 부분 없이 설명하기 수월합니다. 어려운 상황일수록 혼자 추측하기보다 자료를 바탕으로 현재 위치를 확인하는 것이 중요합니다.

개인파산 절차에서는 파산신청과 면책 심사에서 여러 사정이 함께 확인될 수 있습니다. 따라서 사실과 다른 내용을 작성하거나 일부 자료를 누락하기보다, 확인되는 범위에서 성실하게 정리하는 편이 좋습니다. 이 글은 일반적인 법률정보이며, 면책 가능성이나 구체적인 진행 방법은 개인별 상황에 따라 달라질 수 있습니다.

아래 동별 표와 태그는 ${seed.district} 개인파산·면책 정보를 찾을 때 활용할 수 있는 키워드입니다. 지역명으로 검색하더라도 실제 상담에서는 채무·재산·소득·가족 상황을 함께 살펴보게 됩니다.`
  };
};
